        bill!(proof; (usize, usize));
        let mut lower = 0;
        let mut upper = self.len;
        loop {
            bill!(proof; (usize, usize, bool));
            if lower == upper {
                break;
            }
            bill!(proof; (usize, usize, usize));
            let middle = lower + (upper - lower) / 2;
            bill!(proof; 2 * (&[Header<'_>; N], usize, &Header<'_>));
            bill!(proof; 4 * &str);
            bill!(proof; 2 * Ordering);
            #[cfg(test)]
