        proof.charge(&complete);
        if !complete {
            continue;
        }
        let before = proof.roots;
        proof.charge(&before);
        for root in call_identity::roots(function) {
            if !visit(
                root,
                false,
                true,
                0,
                &names,
                &mut directory,
                $authored,
                &mut proof,
            ) {
                proof.roots = before;
                break;
            }
