//! One source traversal, separate auxiliary and local-callee results.
use super::super::shared_local_callees::{Context, Costs, Failure, Session};
use super::{
    call_identity, compiler_dispatch, AuthoredDeclaration, BTreeMap, Expr, ExprKind, ModuleUseKind,
    Names, Program, Proof, Statement,
};
use crate::ast::{Function, Type};
use std::mem::size_of;
type Error = Failure;
type Index<'a> = BTreeMap<&'a str, AuthoredDeclaration<'a>>;

pub(super) struct Loan<'a> {
    pub(super) auxiliary: bool,
    pub(super) local: Option<&'a Function>,
}
impl Loan<'_> {
    pub(super) const NONE: Self = Self {
        auxiliary: false,
        local: None,
    };
}
pub(super) trait Lookup<'p> {
    fn target(
        &mut self,
        authored: &Index<'_>,
        name: &str,
        arity: usize,
        proof: &mut Proof,
    ) -> Loan<'p>;
}
struct Linear<'p> {
    program: &'p Program,
    imports: bool,
}
impl<'p> Lookup<'p> for Linear<'p> {
    fn target(
        &mut self,
        authored: &Index<'_>,
        name: &str,
        arity: usize,
        proof: &mut Proof,
    ) -> Loan<'p> {
        let program = self.program;
        let imports = self.imports;
        proof.charge(&(program, authored, imports, name, arity));
        proof.bytes = proof
            .bytes
            .saturating_add(2 * size_of::<Loan<'_>>() + 2 * size_of::<&mut Self>());
        if compiler_dispatch(name, proof) {
            return Loan::NONE;
        }
        for interface in &program.interfaces {
            proof.charge(&interface);
            for import in &interface.imports {
                proof.charge(&import);
                if import.name == name {
                    return Loan::NONE;
                }
            }
        }
        let mut found = None;
        let mut ambiguous = false;
        let mut local = None;
        for function in &program.functions {
            proof.charge(&function);
            if function.name == name {
                ambiguous |= found.is_some();
                found = Some(function);
                local = Some(function);
            }
        }
        for item in program.module_uses.iter().filter(|_| imports) {
            proof.charge(&item);
            if item.alias != name {
                continue;
            }
            // Any competing nonfunction alias also closes the proof.
            if item.kind != ModuleUseKind::Function {
                return Loan::NONE;
            }
            let Some(header) = authored.get(item.persistent_id.as_str()) else {
                return Loan::NONE;
            };
            proof.charge(&header);
            if header.module != item.target_module {
                return Loan::NONE;
            }
            let Some(function) = header.function else {
                return Loan::NONE;
            };
            proof.charge(&function);
            if function.stable_id != item.persistent_id {
                return Loan::NONE;
            }
            ambiguous |= found.is_some();
            found = Some(function);
            local = None;
        }
        proof.charge(&(found, ambiguous));
        let admitted = !ambiguous
            && found.is_some_and(|f| f.type_parameters.is_empty() && f.params.len() == arity);
        proof.charge(&admitted);
        Loan {
            auxiliary: admitted,
            local: if admitted { local } else { None },
        }
    }
}

fn plain(ty: &Type) -> bool {
    matches!(
        ty,
        Type::I64
            | Type::I32
            | Type::U8
            | Type::Usize
            | Type::Char
            | Type::F32
            | Type::F64
            | Type::Bool
            | Type::String
            | Type::Bytes
            | Type::Str
            | Type::SliceU8
    )
}
fn ordinary_data(function: &Function, proof: &mut Proof) -> bool {
    proof.charge(&(function, &function.params, &function.return_type));
    function.explicit_id
        && function.type_parameters.is_empty()
        && function.yields.is_none()
        && function.follows.is_none()
        && plain(&function.return_type)
        && function.params.iter().all(|p| {
            proof.charge(&p);
            plain(&p.ty)
        })
}
fn supported(expression: &Expr, proof: &mut Proof) -> bool {
    proof.charge(&(expression, &expression.kind));
    // Reuse the existing constructor/statement match. No second child walk or
    // statement iterator is formed for retention. The extra predicate value
    // is accounted independently of the old classifier's returned boolean.
    proof.bytes = proof.bytes.saturating_add(2 * size_of::<bool>());
    if !matches!(
        expression.kind,
        ExprKind::Call { .. }
            | ExprKind::If { .. }
            | ExprKind::Unary { .. }
            | ExprKind::Binary { .. }
            | ExprKind::Var(_)
            | ExprKind::Int(_)
            | ExprKind::Int32(_)
            | ExprKind::Uint8(_)
            | ExprKind::Usize(_)
            | ExprKind::Char(_)
            | ExprKind::Float32(_)
            | ExprKind::Float64(_)
            | ExprKind::Bool(_)
            | ExprKind::Block { .. }
    ) {
        proof.retention_closed = false;
    }
    match &expression.kind {
        ExprKind::Call { .. }
        | ExprKind::If { .. }
        | ExprKind::Unary { .. }
        | ExprKind::Binary { .. }
        | ExprKind::Var(_)
        | ExprKind::Int(_)
        | ExprKind::Int32(_)
        | ExprKind::Uint8(_)
        | ExprKind::Usize(_)
        | ExprKind::Char(_)
        | ExprKind::Float32(_)
        | ExprKind::Float64(_)
        | ExprKind::Bool(_)
        | ExprKind::String(_)
        | ExprKind::BorrowedUtf8Literal(_)
        | ExprKind::ArrayU8(_)
        | ExprKind::RepeatArrayU8 { .. } => true,
        ExprKind::Block { statements, .. } => statements.iter().all(|s| {
            proof.charge(&s);
            match s {
                Statement::Let { declared, .. } => {
                    // The original Option callback now carries this one lender;
                    // its original type loan and plain-result control survive.
                    proof.bytes = proof
                        .bytes
                        .saturating_add(size_of::<&mut Proof>() + 2 * size_of::<bool>());
                    declared.as_ref().is_none_or(|ty| {
                        proof.retention_closed &= matches!(
                            ty,
                            Type::I64
                                | Type::I32
                                | Type::U8
                                | Type::Usize
                                | Type::Char
                                | Type::F32
                                | Type::F64
                                | Type::Bool
                        );
                        plain(ty)
                    })
                }
                Statement::Assign { field: None, .. } | Statement::While { .. } => true,
                _ => {
                    proof.retention_closed = false;
                    false
                }
            }
        }),
        _ => false,
    }
}

