fn visit<'p, 'a, L: Lookup<'p>>(
    expression: &Expr,
    free: bool,
    outside: bool,
    depth: usize,
    names: &Names<'_>,
    lookup: &mut L,
    context: Context<'p, 'a>,
    owner: &'p Function,
    body: bool,
    body_complete: &mut bool,
    session: &mut Option<Session<'p, 'a>>,
    proof: &mut Proof,
) -> Result<bool, Error> {
    proof.charge(&(
        expression,
        free,
        outside,
        depth,
        names,
        &mut *lookup,
        context,
        owner,
        body,
        &mut *body_complete,
        &mut *session,
    ));
