                let scalar = matches!(p.mode, crate::ast::ParamMode::Value)
                    && matches!(
                        p.ty,
                        Type::I64
                            | Type::I32
                            | Type::U8
                            | Type::Usize
                            | Type::Char
                            | Type::F32
                            | Type::F64
                            | Type::Bool
